公式内容:
=IFERROR(
  (IF(
    AND(
      R69 = INDIRECT("对齐度计算!" & "I" & O68, TRUE),
      Q69 <> INDIRECT("对齐度计算!" & "H" & O68, TRUE)
    ),
    IF(
      Q69 < INDIRECT("对齐度计算!" & "H" & O68, TRUE),
      PI(),
      0
    ),
    ACOS(
      MAX(-1, MIN(1,
        (Q69 - INDIRECT("对齐度计算!" & "H" & O68, TRUE)) /
        P68
      ))
    ) * SIGN(
      R69 - INDIRECT("对齐度计算!" & "I" & O68, TRUE)
    )
  ) -
  INDIRECT("对齐度计算!" & "K" & O68, TRUE) *
  IF(
    INDIRECT("对齐度计算!" & "K" & O68, TRUE) * INDIRECT("对齐度计算!" & "K" & (O68+1), TRUE) > 0,
    IF(
      INDIRECT("对齐度计算!" & "L" & O68, TRUE) < INDIRECT("对齐度计算!" & "L" & (O68+1), TRUE),
      PI() - ACOS(
        MAX(-1, MIN(1,
          ABS(
            INDIRECT("对齐度计算!" & "K" & O68, TRUE) * INDIRECT("对齐度计算!" & "L" & O68, TRUE) / 2 -
            INDIRECT("对齐度计算!" & "K" & (O68+1), TRUE) * INDIRECT("对齐度计算!" & "L" & (O68+1), TRUE) / 2
          ) / P68
        ))
      ),
      ACOS(
        MAX(-1, MIN(1,
          ABS(
            INDIRECT("对齐度计算!" & "K" & O68, TRUE) * INDIRECT("对齐度计算!" & "L" & O68, TRUE) / 2 -
            INDIRECT("对齐度计算!" & "K" & (O68+1), TRUE) * INDIRECT("对齐度计算!" & "L" & (O68+1), TRUE) / 2
          ) / P68
        ))
      )
    ),
    ACOS(
      MAX(-1, MIN(1,
        ABS(
          INDIRECT("对齐度计算!" & "K" & O68, TRUE) * INDIRECT("对齐度计算!" & "L" & O68, TRUE) / 2 -
          INDIRECT("对齐度计算!" & "K" & (O68+1), TRUE) * INDIRECT("对齐度计算!" & "L" & (O68+1), TRUE) / 2
        ) / P68
      ))
    )
  )) / PI() * 180,
  "计算错误，请检查参数"
)

